create or replace function private.guard_communication_identity() returns trigger language plpgsql security invoker set search_path=public,private as $$ begin if tg_table_name='conversations' and (new.company_id is distinct from old.company_id or new.created_by is distinct from old.created_by or new.kind is distinct from old.kind) then raise exception 'Conversation identity is immutable'; end if; if tg_table_name='messages' and (new.conversation_id is distinct from old.conversation_id or new.sender_id is distinct from old.sender_id or new.created_at is distinct from old.created_at) then raise exception 'Message identity is immutable'; end if; if tg_table_name='calls' and (new.company_id is distinct from old.company_id or new.conversation_id is distinct from old.conversation_id or new.initiator_id is distinct from old.initiator_id or new.call_type is distinct from old.call_type or new.ticket_id is distinct from old.ticket_id or new.asset_id is distinct from old.asset_id or new.team_id is distinct from old.team_id or new.created_at is distinct from old.created_at) then raise exception 'Call identity is immutable'; end if; return new; end; $$;
create trigger conversations_guard_identity before update on public.conversations for each row execute function private.guard_communication_identity();
create trigger messages_guard_identity before update on public.messages for each row execute function private.guard_communication_identity();
create trigger calls_guard_identity before update on public.calls for each row execute function private.guard_communication_identity();
